inline ::flatbuffers::Offset<AGF> CreateAGF(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> EPOCH = 0,
    ::flatbuffers::Offset<::flatbuffers::String> VALID_START = 0,
    ::flatbuffers::Offset<::flatbuffers::String> VALID_END = 0,
    ::flatbuffers::Offset<::flatbuffers::String> FORECAST_REFERENCE_TIME = 0,
    double FORECAST_LEAD_S = 0.0,
    agfVariable VARIABLE = agfVariable_UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::String> UNITS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> CATEGORY_LABELS = 0,
    agfDType DTYPE = agfDType_UNSPECIFIED,
    double FILL_VALUE = 0.0,
    double SCALE_FACTOR = 1.0,
    double ADD_OFFSET = 0.0,
    uint32_t NX = 0,
    uint32_t NY = 0,
    agfRowOrder ROW_ORDER = agfRowOrder_UNSPECIFIED,
    agfProjection PROJECTION = agfProjection_UNSPECIFIED,
    ::flatbuffers::Offset<AGFProjectionParameters> PROJECTION_PARAMETERS = 0,
    agfPayloadCodec PAYLOAD_CODEC = agfPayloadCodec_UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint8_t>> PAYLOAD = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PAYLOAD_CID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PAYLOAD_SHA256 = 0,
    uint64_t PAYLOAD_SIZE_BYTES = 0,
    ::flatbuffers::Offset<AGFProvenance> PROVENANCE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> DESCRIPTION = 0) {
  AGFBuilder builder_(_fbb);
  builder_.add_PAYLOAD_SIZE_BYTES(PAYLOAD_SIZE_BYTES);
  builder_.add_ADD_OFFSET(ADD_OFFSET);
  builder_.add_SCALE_FACTOR(SCALE_FACTOR);
  builder_.add_FILL_VALUE(FILL_VALUE);
  builder_.add_FORECAST_LEAD_S(FORECAST_LEAD_S);
  builder_.add_DESCRIPTION(DESCRIPTION);
  builder_.add_PROVENANCE(PROVENANCE);
  builder_.add_PAYLOAD_SHA256(PAYLOAD_SHA256);
  builder_.add_PAYLOAD_CID(PAYLOAD_CID);
  builder_.add_PAYLOAD(PAYLOAD);
  builder_.add_PROJECTION_PARAMETERS(PROJECTION_PARAMETERS);
  builder_.add_NY(NY);
  builder_.add_NX(NX);
  builder_.add_CATEGORY_LABELS(CATEGORY_LABELS);
  builder_.add_UNITS(UNITS);
  builder_.add_FORECAST_REFERENCE_TIME(FORECAST_REFERENCE_TIME);
  builder_.add_VALID_END(VALID_END);
  builder_.add_VALID_START(VALID_START);
  builder_.add_EPOCH(EPOCH);
  builder_.add_ID(ID);
  builder_.add_PAYLOAD_CODEC(PAYLOAD_CODEC);
  builder_.add_PROJECTION(PROJECTION);
  builder_.add_ROW_ORDER(ROW_ORDER);
  builder_.add_DTYPE(DTYPE);
  builder_.add_VARIABLE(VARIABLE);
  return builder_.Finish();
}

