  auto VALID_START__ = VALID_START ? _fbb.CreateString(VALID_START) : 0;
  auto VALID_END__ = VALID_END ? _fbb.CreateString(VALID_END) : 0;
  auto FORECAST_REFERENCE_TIME__ = FORECAST_REFERENCE_TIME ? _fbb.CreateString(FORECAST_REFERENCE_TIME) : 0;
  auto UNITS__ = UNITS ? _fbb.CreateString(UNITS) : 0;
  auto CATEGORY_LABELS__ = CATEGORY_LABELS ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*CATEGORY_LABELS) : 0;
