inline const AGF *GetAGF(const void *buf) {
  return ::flatbuffers::GetRoot<AGF>(buf);
}

inline const AGF *GetSizePrefixedAGF(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<AGF>(buf);
}

inline const char *AGFIdentifier() {
  return "$AGF";
}

inline bool AGFBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, AGFIdentifier());
}

inline bool SizePrefixedAGFBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, AGFIdentifier(), true);
}

template <bool B = false>
inline bool VerifyAGFBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<AGF>(AGFIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedAGFBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<AGF>(AGFIdentifier());
}

inline void FinishAGFBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<AGF> root) {
  fbb.Finish(root, AGFIdentifier());
}

inline void FinishSizePrefixedAGFBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<AGF> root) {
  fbb.FinishSizePrefixed(root, AGFIdentifier());
}

